#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll INF = 1LL << 60;

struct Edge {
    int a, b;
    ll w;
};

struct Bellman {
    int n;
    vector<Edge> e;
    vector<vector<int>> adj;
    vector<ll> d;
    vector<int> par, bad;

    Bellman(int _n) {
        n = _n;
        adj.resize(n + 1);
        d.assign(n + 1, INF);
        par.assign(n + 1, -1);
        bad.resize(n + 1);
    }

    void add(int a, int b, ll w) {
        e.push_back({a, b, w});
        adj[a].push_back(b);
    }

    void run(int s) {
        d[s] = 0;
        for (int i = 1; i < n; i++) {
            bool changed = false;
            for (auto [a, b, w] : e) {
                if (d[a] == INF) continue;
                ll nd = d[a] + w;
                if (nd < d[b]) {
                    d[b] = nd;
                    par[b] = a;
                    changed = true;
                }
            }
            if (!changed) break;
        }
        queue<int> q;
        for (auto [a, b, w] : e) {
            if (d[a] != INF && d[a] + w < d[b] && !bad[b]) {
                bad[b] = 1;
                q.push(b);
            }
        }
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int u : adj[v]) {
                if (!bad[u]) {
                    bad[u] = 1;
                    q.push(u);
                }
            }
        }
    }

    vector<int> path(int t) const {
        if (d[t] == INF || bad[t]) return {};
        vector<int> p;
        for (int v = t; v != -1; v = par[v]) p.push_back(v);
        reverse(p.begin(), p.end());
        return p;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, s, q;
    cin >> n >> m >> s >> q;
    Bellman bf(n);
    while (m--) {
        int a, b;
        ll w;
        cin >> a >> b >> w;
        bf.add(a, b, w);
    }
    bf.run(s);
    while (q--) {
        int t;
        cin >> t;
        if (bf.bad[t]) cout << "-INF\n";
        else if (bf.d[t] == INF) cout << "UNREACHABLE\n";
        else {
            auto p = bf.path(t);
            cout << bf.d[t] << ' ' << p.size();
            for (int v : p) cout << ' ' << v;
            cout << '\n';
        }
    }
    return 0;
}

floyd-basic:
#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll INF = 1LL << 60;

struct Floyd {
    int n;
    vector<vector<ll>> d;

    Floyd(int _n) {
        n = _n;
        d.assign(n + 1, vector<ll>(n + 1, INF));
        for (int i = 1; i <= n; i++) d[i][i] = 0;
    }

    void add(int a, int b, ll w) {
        d[a][b] = min(d[a][b], w);
        d[b][a] = min(d[b][a], w);
    }

    void run() {
        for (int k = 1; k <= n; k++) {
            for (int i = 1; i <= n; i++) {
                if (d[i][k] == INF) continue;
                for (int j = 1; j <= n; j++) {
                    if (d[k][j] == INF) continue;
                    d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
                }
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    cin >> n >> m >> q;
    Floyd fw(n);
    while (m--) {
        int a, b;
        ll w;
        cin >> a >> b >> w;
        fw.add(a, b, w);
    }
    fw.run();
    while (q--) {
        int a, b;
        cin >> a >> b;
        cout << (fw.d[a][b] == INF ? -1 : fw.d[a][b]) << '\n';
    }
    return 0;
}

floyd-general:
#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll INF = 1LL << 60;

struct Floyd {
    int n;
    vector<vector<ll>> d;
    vector<vector<int>> nxt, bad;

    Floyd(int _n) {
        n = _n;
        d.assign(n + 1, vector<ll>(n + 1, INF));
        nxt.assign(n + 1, vector<int>(n + 1, -1));
        bad.assign(n + 1, vector<int>(n + 1));
        for (int i = 1; i <= n; i++) {
            d[i][i] = 0;
            nxt[i][i] = i;
        }
    }

    void add(int a, int b, ll w) {
        if (w < d[a][b]) {
            d[a][b] = w;
            nxt[a][b] = b;
        }
    }

    void run() {
        for (int k = 1; k <= n; k++) {
            for (int i = 1; i <= n; i++) {
                if (d[i][k] == INF) continue;
                for (int j = 1; j <= n; j++) {
                    if (d[k][j] == INF) continue;
                    ll nd = max(-INF, d[i][k] + d[k][j]);
                    if (nd < d[i][j]) {
                        d[i][j] = nd;
                        nxt[i][j] = nxt[i][k];
                    }
                }
            }
        }
        for (int k = 1; k <= n; k++) {
            if (d[k][k] >= 0) continue;
            for (int i = 1; i <= n; i++) {
                if (d[i][k] == INF) continue;
                for (int j = 1; j <= n; j++) {
                    if (d[k][j] != INF) bad[i][j] = 1;
                }
            }
        }
    }

    vector<int> path(int a, int b) const {
        if (d[a][b] == INF || bad[a][b]) return {};
        vector<int> p = {a};
        while (a != b) {
            a = nxt[a][b];
            p.push_back(a);
        }
        return p;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    cin >> n >> m >> q;
    Floyd fw(n);
    while (m--) {
        int a, b;
        ll w;
        cin >> a >> b >> w;
        fw.add(a, b, w);
    }
    fw.run();
    while (q--) {
        int a, b;
        cin >> a >> b;
        if (fw.bad[a][b]) cout << "-INF\n";
        else if (fw.d[a][b] == INF) cout << "UNREACHABLE\n";
        else {
            auto p = fw.path(a, b);
            cout << fw.d[a][b] << ' ' << p.size();
            for (int v : p) cout << ' ' << v;
            cout << '\n';
        }
    }
    return 0;
}
